import { test, expect } from '@playwright/test';

test.describe('User Profile - Connect Google Account', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
    await page.getByRole('button', { name: /login/i }).click();
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: /submit/i }).click();
    await expect(page.getByText(/welcome, testuser/i)).toBeVisible();
  });

  test('should display connect Google account button', async ({ page }) => {
    await expect(page.getByRole('button', { name: /connect google account/i })).toBeVisible();
  });

  test('should connect Google account successfully', async ({ page }) => {
    await page.getByRole('button', { name: /connect google account/i }).click();
    await page.getByLabel('Email or phone').fill('testuser@gmail.com');
    await page.getByRole('button', { name: /next/i }).click();
    await page.getByLabel('Enter your password').fill('googlepassword123');
    await page.getByRole('button', { name: /next/i }).click();
    await expect(page.getByText(/google account connected successfully/i)).toBeVisible();
  });
});
